macro_rules! maximum {
    ($first:expr) => { $first };
    ($first:expr, $($rest:expr),+) => {{
        let first = $first;
        let rest = maximum!($($rest),+);
        if first > rest { first } else { rest }
    }};
}

println!("{}", maximum!(3, 9, 2, 7));

